(window.webpackJsonp=window.webpackJsonp||[]).push([[102],{542:function(t,s,v){"use strict";v.r(s);var _=v(11),e=Object(_.a)({},(function(){var t=this,s=t.$createElement,v=t._self._c||s;return v("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[v("p",[v("font",{attrs:{size:"5"}},[t._v("摘要：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("1、虽然不是每个人都奉召为使徒，但所有被神所爱的人，都奉召有了一个共同的身份，就是圣徒，并有一个共同的使命，就是成为圣洁。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("2、这种身份、使命是共同的，但也是抽象的。而具体到每个圣徒个人，神又会在这个共同的、抽象的身份和使命下，召他们成为具体的、特别的身份，并在这个身份下，赋予他们一个具体的、特别的使命。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("3、对大部分人而言，你现在的身份，就是主所召你的具体、特别的身份，你在这个身份上该做的事，就是现在主所赋予你具体的、特别的使命。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("4、在现有的身份中，要出于荣耀神的目的而做、存要存谦卑的心而做、对人有怜悯而做、行公义之事，这就是在做圣徒、执行你的使命。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("5、我们都鄙视犹大，或者为犹大感到惋惜。但有没有可能其实你自己就是犹大？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("6、我们要充分认识到，你每天的朝九晚五、忙忙碌碌、鸡毛蒜皮、柴米油盐酱醋茶，这些不是无意义、单调的生活，而正是神对你的呼召具体落实的地方。既然你认识神、爱神，那么我们理应为这位掌管全地、但又爱我们的君王的呼召而感到光荣、兴奋、充满盼望、充满干劲。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("7、同时，我们也要保持警醒，要知道自己是败坏的、是有背叛神的倾向的。因此谦卑在神面前，牢牢抓住他，祈求他，让他来保守我们到底。而神是有怜悯的，我们祈求，就必得着。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家平安。今天我们讲的经文是路加福音6:12~16节。上一次我们讲了路加福音6:1~11节，关于安息日的经文。我上次有提到，教会中很多人对这段经文有错误的理解。一种错误理解是认为这段是在说“照顾人的需要是第一位的，神的律法要让位于人的需要”。第二种错误理解，是认为这段经文是表达“主耶稣可以随心所欲地对包括安息日在内的神的律法进行解释”。这些都是错误的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("主耶稣在这里是在攻击当时的犹太教对神的律法那种错误的、违背旧约圣经的、律法主义式的理解方式，并且揭示出一种符合旧约圣经的、正确的理解方法。一言以蔽之，耶稣是在攻击当时犹太教的根基。这个根基不是犹太教的经典，旧约圣经本身，而是对就旧约圣经的解释方法。根基错了，那么一切都错了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以在6:11节记载，当时在场的文士和法利赛人才会勃然大怒，彼此商议要怎样处治耶稣。路加在这里用了一个比较含蓄的词“处治”，在马太福音和马可福音的平行经文中我们可以看到，他们所谓的“处治”，实际上是要除灭耶稣，也就是商议如何把他杀了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们可以看到，犹太的宗教代表们此时已经对这场弥赛亚运动的主角——拿撒勒人耶稣做出了第三个重大决定：这是个异端，应该被除灭。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("一、背景信息")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我在讲路加福音5:12~32节的时候曾经给大家补充过一段当时历史背景。如果不明白这些背景，你在理解一些经文的时候，就会有盲人摸象的混乱感。我再把这个背景重复一次：当时的犹太人都在盼望着旧约圣经中所预言的弥赛亚到来、把他们从罗马统治的铁蹄下拯救出来，恢复大卫、所罗门王朝的荣耀。在这样的氛围下，就会不时有人出来声称自己就是弥撒亚，鼓动群众，然后不时在犹太人中形成一场又一场的“弥赛亚运动”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以当时的犹太公会就制定了一套包含两个阶段的调查方案来对出现的各种“弥赛亚运动”进行调查。第一个阶段是由整个犹太地区的宗教代表来进行观察，看这个“弥赛亚”做了什么、说了什么。这个阶段，他们是不允许发问的。在这之后，他们会向耶路撒冷的公会进行汇报，以判断这个弥赛亚运动是否真的特殊或者重要。如果他们认为是无关紧要的，不会有什么影响力，那么调查就会终止；否则的话，就会进入到调查的第二个阶段，进行更仔细的调查。在这个阶段，他们会对被视为弥赛亚的个人或运动的成员进行发问。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("接下来呢，我们就带着这样的历史背景，一起来浏览一下前面的经文，这样我们就能更好地理解今天我们要讲的这段经文所记载的事件发生的背景了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("首先就是路加福音5:12~16节，这里记载了耶稣医治麻风病人这个事情。这个事情是促使犹太公会启动整个调查程序的原因。因为在当时的拉比眼中，医治麻风病这不是一个一般的神迹，而是一个弥赛亚才会行的神迹。所以当耶稣医治这个麻风病人后，在5:14节嘱咐他不要告诉别人，只是把身体给祭司查看。耶稣实际上是想私下向犹太的宗教领袖们传达一个信息：你们的弥赛亚来了。我们不确定这个被医治的人是否真去找了祭司，但从经文中我们能确定的是，他违背了耶稣的嘱咐，向很多人都说了这件事情，于是有极多的人聚集到耶稣这里来要跟随他。形成了一场弥赛亚运动。而这一定会被犹太公会注意到。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以耶稣知道他的事工的第一个转折点到了：他会被犹太宗教领袖们调查，他要开始与他们打交道了。于是我们看到在5:16节记载，耶稣这时退到旷野去祷告。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而犹太的宗教领袖们也确实注意到了这场弥赛亚运动，于是对耶稣做了第一个重大决定：启动调查。所以在5:17，我们看到全国各地的宗教代表都来到耶稣那里，观察耶稣的言行。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在那时候，耶稣宣告他有赦罪的权柄，引起了在场的犹太宗教代表的不满。但由于还处在第一个调查阶段，因此不满也只能在心里表达（5:22）。同时，他还行了一个医治瘫子的神迹，引起全场轰动（5:26）。这些宗教代表显然会把这些事情都汇报到耶路撒冷，耶稣的言行足以让犹太宗教领袖们对他做出第二个重大决定：就是启动第二阶段的调查。这个阶段，调查人员会对被视为弥赛亚的个人或运动的成员进行发问。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("于是我们看到，在5:27~32节，法利赛人质疑耶稣与税吏和罪人交往；在5:33~39节，他们质疑耶稣门徒们不禁食；在6:1~11节，他们就安息日的问题与耶稣进行交锋。在这些互动中，耶稣都在越来越深地打击法利赛人对旧约的理解方式。按照耶稣的论证，法利赛人的方法论就是错的，因此对旧约的解释当然是错的，基于这种错误的解释所发展出来的一整套教义，也当然都是错的了。这就动摇了犹太人的根基。因此，犹太的宗教人士现在可以结束第二阶段的调查了。经过这个调查，他们对耶稣做了第三个决定：这是一个异端，并且会造成很大的影响。既然是这样，就要想办法把他出灭掉。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("二、认识呼召")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这就是我们今天这段经文的背景。从此之后，耶稣的事工又迎来了一个转折点：犹太宗教领袖们已经决定要杀了他，他需要在这样的背景下来开展事工，并最终走向十字架。和第一个转折点时一样，路加在6:12节记载，这个时候，耶稣出去祷告，并且强调，是整夜地向神祷告。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("祷告的具体内容我们无从可知，但从后面的经文中可以看到，这一夜的祷告其中一个最主要的目的，是他要寻求天父的旨意，如何安排他的后事。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而他显然也得到了天父的旨意，并且立即执行。第13节说，到了天亮，他没有耽搁，立即叫了他的门徒来，从中挑选了十二个人，称他们为使徒。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以，从门徒中设立十二个使徒，是神要求他为预备后事所做的第一件事情。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“使徒”这个词的原始意义，就是被派出去传消息的人。耶稣死后，需要有人继续去把他和他的福音传播出去，所以先指定人，是首先要做的事。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在指定了人之后、他们正式开始工作之前，需要对这些人进行培训，这就是耶稣接下来的事工中一项很重要的工作。所以如果我们去看马可福音3:14的平行经文，讲到耶稣设立了他们之后，“就要他们常和自己同在，也要差他们去传道，并给他们权柄赶鬼。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“常和自己同在”，就是以身作则，亲自示他们做示范；“差他们去传道，并给他们权柄赶鬼”，用我们现在话讲，就是提供实习机会，让他们自己去做做看。做了之后，他加以点评指导，促进他们工作能力的提升。这样在他离开后，他们才能比较好地独立开展工作。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("耶稣当时的这些考虑和打算，这些门徒们当然是意识不到的。在他们的眼中，耶稣是他们的拉比，更是他们一直在盼望的弥赛亚。在他们的认知当中，这位弥赛亚是一位政治上的君王，要带领他们推翻罗马人的统治，重新恢复大卫、所罗门时期的荣耀。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而这天早晨，这样一位未来的大君王把他们叫上山，呼召出这十二个人来重点培养。大家想一下，如果你是那十二个人中的其中一个，你会是什么感觉？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你有没有过被某个你觉得很厉害的人特别选择、特别呼召或者特别委以重任的经历？这个人可能是你的导师，或你的老板。能否回忆一下那个时候，并捕捉到你当时的感觉？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果你实在无法理解。那么可以设想一下，你现在穿越回了1928年，到了井冈山。有一个叫毛泽东的人，他邀请你进入他的核心圈子。因为你是穿越回去的，所以你确信他未来会有怎样的政治地位，而你现在被他特别邀请。我想正常人，都会有一种荣幸、兴奋、充满了期待、充满干劲的感觉，对不对？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这就是当时这些门徒们，尤其是那些被选为使徒的人的心态。他们虽然不是从未来穿越到了那个时候，但他们提前从旧约圣经、犹太拉比们的教导中得知并确信，他们的弥赛亚会复兴以色列，会使万邦来朝，会使以色列国成为这个世界的中心。而他们相信，在他们面前的这位耶稣，就是这位弥赛亚；而这位弥赛亚，现在拣选了自己、让自己进入了他的核心圈子、对自己委以重任。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我想，这十二个人同样觉得荣幸、兴奋、充满期待、充满干劲，对不对？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这是这十二个人，他们奉召为使徒之时的心态；这十二个人中还缺少了一个后来影响巨大的使徒，就是保罗，但我们同样可以想见，当保罗在奉召的时候，他应该也是同样的心态，对不对？我们一起来翻一翻罗马书。看一看保罗怎么描述他自己的：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们看罗马书的开篇：“耶稣基督的仆人保罗，奉召为使徒，特派传神的福音。”我不知道大家，我自己每次读罗马书第一句话这里，都会感受到一种气势。我一直在想这种气势是什么。后来我捕捉到了，这就像一个被差派宣告皇帝圣旨的大臣气势：我是钦差，你们地方上谁敢动我？有这样一种气势在。这种气势来自于他对自己的身份、使命的光荣感，我是被耶稣基督，这宇宙的主所召的人！我的使命是他委任的工作！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("保罗因着这种身份、使命而有光荣感，我相信当时这十二个使徒也有。那在座的弟兄姐妹们，你们有没有？你当然没有被召为使徒，因此你也没有像使徒一样，被特别地差派去传神的福音。但你有没有被耶稣所召而有了一个特别的身份呢？耶稣有没有在这身份下赋予你重大的使命呢？更重要的是，你是否因着这身份、使命而感到光荣、兴奋、充满了期待、充满干劲呢？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("罗马书1:1节，保罗说他是“奉召为使徒”；我们来看罗马书1:7节保罗如何称呼那些在罗马教会的众人呢？“奉召为圣徒”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("看到没有？虽然不是每个人都奉召为使徒，但所有被神所爱的人，都奉召有了一个共同的身份，就是圣徒。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那你是不是为这个身份感到光荣？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在这个身份下，神把一个共同的使命，给了每个做圣徒的人。这个使命是什么？我们来看帖撒罗尼迦前书4:1~3节，保罗说“我们靠着主耶稣求你们、劝你们，你们既然受了我们的教训，知道该怎样行可以讨神喜悦，就要照你们现在所行的更加勉励。你们原晓得，我们凭着主耶稣传给你们的命令。”也就是耶稣通过使徒们给每个做圣徒的人一个共同的命令，当然我们也可以叫使命，就是给你一个任务你去做。这个任务是什么呢？第3节说，“你们要成为圣洁。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以成为圣洁，就是在执行神的命令、完成神交付的任务，就可以讨神喜悦。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("成为圣洁，这就是耶稣在圣徒这个身份下给你的使命。那你是不是为这个使命感到光荣、兴奋、充满了期待、充满了干劲？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我上面说的，是神给每个他所拣选的人的一个共同的身份、共同的使命。这种身份、使命是共同的，但也是抽象的。而具体到每个圣徒个人，神又会在这个共同的、抽象的身份和使命下，召他们成为具体的、特别的身份，并在这个身份下，赋予他们一个具体的、特别的使命。对今天经文中那十二个人是如此，对保罗是如此，对我们每个人也同样如此。对于那十二个人，对于保罗，神召他们的具体、特别的身份是使徒、传消息的，赋予他们具体的、特别的使命就是去传他的福音（所以保罗罗马书1:1节说自己是被“特派”传神的福音）。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("神对不同的人有不同的具体的呼召。圣经是怎么说的呢？我们来看哥林多前书7:17。这里说“只要照主所分给各人的，和神所召各人的而行”。也就是说，神召你干什么，这就是神给你个人的具体的、特别的身份和使命。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("耶稣如果像今天的经文中那样，把我叫上山，告诉我，你以后是使徒了，然后做这个做那个，我当然知道他给我的具体、特别的身份和使命是什么；或者耶稣像对保罗那样，突然向他显现，告诉他以后你去外邦人那儿去传福音，我当然也知道他给我的具体、特别的身份和使命是什么。但如果耶稣没有这样明确地向我显现、在我耳边对我说话，那我怎么知道他给我的具体使命、身份是什么？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("哥林多前书7章下面就回答这个问题。我们来看第20节说：“各人蒙召的时候是什么身份，仍要守住这身份”；第24节“你们个人蒙召的时候是什么身份，仍要在神面前守住这身份”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("守住这身份干什么？当然就是继续做这个身份下面要做的事。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以你现在的身份，就是主所召你的具体、特别的身份，你在这个身份上该做的事，就是现在主所赋予你具体的、特别的使命。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你是丈夫吗？这是主召你的身份。但不是一般的丈夫，而是在丈夫的身份中做圣徒。丈夫的使命是什么？是爱妻子，为自己的妻子舍己；是不惹儿女的气。这就是主所赋予你的具体的、特别的使命。所以也不是一般做丈夫，而是在做丈夫中成为圣洁、体现出圣洁的生命来。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果你是学生。这就是主召你的身份。但不是一般的学生，而是在学生的身份中做圣徒。学生的使命是什么？主要是学习。这就是主所赋予你的具体的、特别的使命。也不是一般的学习，而是在学习中成为圣洁、体现出圣洁的生命来。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你是老师吗？这就是主召你的身份。但不是一般的老师，而是在老师的身份中做圣徒。老师的使命是什么？是教书育人。这就是主所赋予你的具体的、特别的使命。也不是一般的教书育人，而是在教书育人中成为圣洁、体现出圣洁的生命来。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我顺便插一个问题问问大家：你怎么就能在学习、教书育人中体现出圣洁的生命来了？这是我之前几次讲道反反复复讲过的内容，还记得吗？刚才我们在帖撒罗尼迦后书4:1~3节是怎么说的？成为圣洁就是讨神喜悦的事，对不对？那神喜悦你做善事还是恶事？当然是善事。所以成为圣洁就是做善事。那什么是神眼中的善事？弥迦书6:8：“行公义、好怜悯、存谦卑的心，与神同行”。就是耶和华眼中的善。我们把这个归纳成了三个要素：第一是动机，你要与神同行，要出于荣耀神的目的；第二是心态，你要存谦卑的心，对人要有怜悯；第三是行为本身，你要行公义。就是说这个行为本身要符合公义，也就是不能违背神的律法。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么学习、教书育人本身，并不违背神的律法，是不是？所以你是否在学习、教书育人中体现出圣洁的生命来，主要是看你的动机和心态是怎样的。你是不是在动机上为了荣耀神而做？你是不是在心态上谦卑地做？你是不是带着对人的怜悯来做？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们这里只是举了丈夫、学生、教师这几个身份作为例子。我们不同的人有不同的身份，甚至在不同的场合都有不同的身份。这些就是我们每个人奉召成为的具体的、特别的身份，我们就是在这些身份中来做圣徒。那我问大家，你是否为你的这个身份感到光荣、兴奋、充满了期待、充满了干劲？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而这些身份下该做的事，就是神赋予我们每个人我们圣徒具体的、特别的使命，我们在做这些事中来完成神赋予我们的“成为圣洁”的使命。那我问大家，你是不是对你这个使命感到光荣、兴奋、充满了期待、充满了干劲？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果答案是否定的，可能是因为三种原因：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第一，你确实没有奉召；")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第二，你看不上神的呼召你成为的身份、看不上他赋予你的使命，因为你有一个自己更想要的身份和使命；")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第三，你从来不知道神原来大多数情况下是这样召人的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果是因为第三种原因，那我今天告诉你了。接下来你就需要结合你自己的情况，好好认清神呼召你具体如何做一个圣徒、具体如何成为圣洁。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果是第二种原因，那你要想清楚，你看不上神的呼召，那你看得上什么？并且我还要再送给你一句神曾经对以色列的祭司以利说过的话： “尊重我的，我必看重他；藐视我的，他必被轻视”（撒母耳记上2:30）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果是第一种原因，那么你需要重新问自己，是否真的知道福音是什么？是否相信福音的全部内容。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("三、始终警醒")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("好，我们再次回到今天的经文。第14~16节，路加列出了这十二个使徒的名单。我们刚才已经讲了，他们认识到耶稣是弥赛亚，被这位巨牛的人特别呼召出来承担使徒的工作，此时心里一定是感到光荣、兴奋、充满了期待、充满了干劲。每个人当时一定都是如此，包括了路加最后提到的这位加略人犹大。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但路加他作为一个历史记录者，当然知道这些人后来都发生了什么。于是在这里，他给加略人犹大加了一个修饰：卖主的。犹大后来出卖耶稣的故事我们当然都是很清楚的。但大家要知道，在路加福音6:12~16所记载的这件事发生的时候，加略人犹大是不知道自己有一天会出卖主耶稣、落得个千古骂名的。他当时还在为自己被召为使徒而兴奋、期待、充满干劲，和其他人十一个人一样。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那犹大是如何被召为十二个使徒之一的呢？我们来看马可福音第3章。第13节说，耶稣上了山，“随自己的意思叫人来。他们便来到他那里，他就设立十二个人。”这里说是耶稣自己选的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们说过，耶稣道成肉身，是圣子在神性上添加了人性，并且抑制住自己的神性，作为人在世上生活。所以圣子在人性中，并不是无所不知的。除非神给他启示，他是无法预计将来的情况的。所以耶稣在把加略人犹大选为十二使徒之一时，如果神给了他关于将来事情的启示，他会知道这个人会出卖自己；如果神没有给他启示，他就不会知道这个人会出卖他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但弟兄姐妹们，耶稣知道还是不知道，其实不是重点。重点是耶稣是“随自己的意思”选的。虽然马可是这样写的，但我们知道，耶稣做出这个选择，是经过了一整夜的祷告；而且我们也知道，耶稣其实从来不会违背神的意思。在约翰福音5:30节，耶稣自己就说“我不求自己的意思，只求那差我来者的意思。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以有可能的情况是，在经过了一整夜的祷告后，神指示了耶稣他应该选择谁来作为使徒；当然我个人认为更有可能的情况是，经过一整夜祷告，神只是告诉他你要为你死后的事做准备了，而并没有明示要选谁，而是把选择权给了耶稣自己。无所不知的神，当然也知道耶稣会选择加略人犹大。所以无论是哪种情况，我们可以说，对于加略人犹大的入选，天上的神都是同意的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这样一来，问题就来了。即使耶稣不知道犹大最终会叛变，但神一定是知道的。那神为何会同意他被召为使徒？这个理由我只简单说一下，不过多做解释，因为往下解释，就涉及到了很多比较深的神学理论。这个理由就是，神要用犹大来实现他让耶稣上十字架的计划。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("现在我们再回到这十二个人被选为使徒的场景，我们把天上的神也拉入这个画面当中。在地上那十二个人，包括加略人犹大，正在为自己奉召而感到光荣、兴奋、充满了期待、充满了干劲；但在天上，神看着这一切，他知道这个正在兴奋的、感到幸福的犹大，最终会出卖耶稣，会上吊自杀，身子扑倒，肚腹崩裂，肠子流出、经受永远的刑罚。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，我每每想到这个画面，就会战惊不已。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("刚才我们讲了，神召我们成为圣徒，给了我们要成为圣洁的使命，我们会感到光荣、兴奋、充满了期待、充满了干劲。大家即使还不能从刚才我提到的一些更具体、个人化的生活场景中去认识自己的呼召和使命，但我想每个人起码都会认识到自己圣徒的身份，知道这个身份会给你带来的荣耀，并为此喜乐、幸福、盼望；在大家刚信主的时候，可能尤其如此。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但当你在这地上喜乐、幸福、盼望的时候，在天上的神他注视着你，会不会也像当年他看到被选为使徒的加略人犹大一样，他同时也看到了你的背叛、看到了你在那火湖里永远受罚？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("换句话说，当我们为着神拣选了我们而感谢主、而幸福、兴奋、充满盼望、充满干劲的时候，你怎么知道你不是加略人犹大？要知道，当时的犹大也是这样的啊！你没有想过要背叛主？当时的犹大也没有想过啊！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("况且这种事不仅仅发生在两千年前的犹大身上，现在就仍常常发生在我们身边。今年是我奉召为圣徒的第十一年。我已经见到过不少牧者离弃真道，在毁灭的道路上一路狂奔；我也见到过更多的普通信徒离弃主耶稣，回到世界的怀抱当中。但在这离弃之前，他们难道没有过为自己奉召而感到荣幸、兴奋、充满盼望、充满干劲的时候吗？我想你们可能看到的这种人，比我还多。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("会不会我现在这样，像过去的他们一样；但将来有一天，我变成他们现在的样子？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你会不会？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们都鄙视犹大，或者为犹大感到惋惜。但有没有可能其实你自己就是犹大？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们不知道。正像当时的加略人犹大不知道一样。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但感谢神，他让路加在这段经文中特别提醒我们，这个在为自己奉召而兴奋的人，最后会出卖主耶稣。于是我们就可以从他得到警戒。于是我们就可以常常把刚才我给大家勾勒的那幅画面拿出来回想：地上的犹大在兴奋着、幸福着、希望着，而天上的神看着他，看到的是他将来的惨状。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("每每这个时候，我就战惊。这种战惊就会促使我向神祷告：主啊，我不知道。我只求你不要像对加略人犹大那样对待我。你知道我是很败坏的，我是很软弱的，我天性中就有背叛你的趋势，所以祈求你一直把我带在身边，你来管教我，你来约束我，你让我为你的名走在这条正路上面。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，希望通过今天我对这短短五节经文的分享，大家能够对自己所蒙的呼召有一个正确的认识。并且因着这种认识，而产生出一种平衡、健康的心态来。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们要充分认识到，神对使徒们的呼召是崇高的、给他们的使命是神圣的。对我们每个人也是这样。你每天的朝九晚五、忙忙碌碌、鸡毛蒜皮、柴米油盐酱醋茶，这些不是无意义、单调的生活，而正是神对你的呼召具体落实的地方。既然你认识神、爱神，那么我们理应为这位掌管全地、但又爱我们的君王的呼召而感到光荣、兴奋、充满盼望、充满干劲。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("同时，我们也要保持警醒，要知道自己是败坏的、是有背叛神的倾向的。因此谦卑在神面前，牢牢抓住他，祈求他，让他来保守我们到底。而神是有怜悯的，我们祈求，就必得着。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当我们一直以这样的心态来持续下去，在我们死的那日，我们就可以自豪地说：“那美好的仗我已经打过了，当跑的路我已经跑尽了，所信的道我已经守住了。从此以后，有公义的冠冕为我存留。就是按着公义审判的主道那日要赐给我的！”")])],1)])}),[],!1,null,null,null);s.default=e.exports}}]);